const execution = $input.first().json.execution || {};
const error = $input.first().json.error || {};
const workflow = $input.first().json.workflow || {};

let message = error.message || 'Unknown automation execution failure';

// Redact any potential PII (SSN, PAN, Account numbers)
message = message.replace(/\b\d{3}-\d{2}-\d{4}\b/g, '[REDACTED_SSN]');
message = message.replace(/\b[A-Z]{5}[0-9]{4}[A-Z]{1}\b/g, '[REDACTED_PAN]');

return [{
  json: {
    workflow_name: workflow.name || 'Mortgage Automation Workflow',
    execution_id: execution.id || 'N/A',
    failed_node: error.node?.name || 'Unknown Node',
    sanitized_error: message,
    occurred_at: new Date().toISOString()
  }
}];

const errorInfo = $('Sanitize Error & Redact PII').item.json;
return [{
  json: {
    alert: 'INCIDENT_RECORDED',
    severity: 'CRITICAL',
    workflow: errorInfo.workflow_name,
    node: errorInfo.failed_node,
    error: errorInfo.sanitized_error,
    logged_to_audit_ledger: true,
    timestamp: new Date().toISOString()
  }
}];
